// Included within the core test namespace, after require/rejected helpers.
void pattern_clipboard_tests(const std::filesystem::path& dir,const std::wstring& segmentPath,const std::wstring& stylePath){
    const auto base=dir/L"pattern-clipboard";std::filesystem::create_directories(base);const auto original=read_file(stylePath),segment=read_file(segmentPath);StyleDocument plain;plain.load(original);
    require(plain.patterns().size()==1&&plain.part_references(0).size()==1&&plain.part_notes(plain.part_references(0)[0].partIndex).size()==4,"saved authored Pattern fixture");
    auto enriched=Chunk::parse(original);auto part=enriched.find("LIST","part"),pattern=enriched.find("LIST","pttn");
    part->find("prth")->data.insert(part->find("prth")->data.end(),{0xde,0xad,0xbe});part->find("prth")->padding=0xa5;
    auto& notes=part->find("note")->data;Bytes extended(4);put32(extended,0,28);for(size_t i=4;i<notes.size();i+=24){extended.insert(extended.end(),notes.begin()+i,notes.begin()+i+24);extended.insert(extended.end(),{0xa1,0xb2,0xc3,0xd4});}notes=extended;
    Chunk opaque;opaque.id="zzzz";opaque.data={7,8,9};opaque.padding=0xc5;part->children.push_back(opaque);pattern->children.push_back(opaque);pattern->find("ptnh")->data.push_back(0xee);pattern->find("ptnh")->padding=0xb5;
    auto ref=*pattern->find("LIST","pref");ref.find("prfc")->data.push_back(0xfa);ref.find("prfc")->padding=0xd5;put32(ref.find("prfc")->data,24,6);pattern->children.push_back(ref);
    StyleDocument source;const auto sourceBytes=enriched.encode();source.load(sourceBytes);const auto payload=source.copy_pattern(0);
    require(source.save_bytes()==sourceBytes&&!source.dirty()&&!source.undo()&&source.copy_pattern(1).empty(),"copy read only and invalid selection empty");
    const auto packet=Chunk::parse(payload);require(packet.type=="SPC1"&&packet.children.size()==2,"shared references export one owned Part");
    StyleDocument destination;destination.load(sourceBytes);require(destination.paste_pattern(payload,L"Independent Paste"),"same identity paste with fresh Part");const auto pasted=destination.save_bytes();
    const auto oldId=source.part_references(0)[0].objectId;const auto newRefs=destination.part_references(1);require(destination.parts().size()==2&&newRefs.size()==2&&newRefs[0].objectId!=oldId&&newRefs[0].objectId==newRefs[1].objectId&&newRefs[1].pchannel==6u,"fresh identity preserves internal sharing and channel");
    auto normalized=Chunk::parse(pasted);normalized.children.pop_back();normalized.children.pop_back();require(normalized.encode()==sourceBytes,"paste retains destination whole bytes");
    auto expected=enriched;auto copiedPart=*enriched.find("LIST","part"),copiedPattern=*enriched.find("LIST","pttn");std::copy(newRefs[0].objectId.begin(),newRefs[0].objectId.end(),copiedPart.find("prth")->data.begin()+132);for(auto& c:copiedPattern.children)if(c.type=="pref")std::copy(newRefs[0].objectId.begin(),newRefs[0].objectId.end(),c.find("prfc")->data.begin());copiedPattern.find("LIST","UNFO")->find("UNAM")->data=utf16(L"Independent Paste");expected.children.push_back(copiedPart);expected.children.push_back(copiedPattern);
    require(expected.encode()==pasted,"only imported GUIDs/name differ including stride tails padding");
    require(destination.undo()&&destination.save_bytes()==sourceBytes&&!destination.dirty()&&destination.redo()&&destination.save_bytes()==pasted,"paste one UndoRedo transaction exact identities");
    require(destination.edit_part_note(newRefs[0].partIndex,0,{0,192,0,0xffffffffu,64,90})&&destination.part_notes(0)[0].musicValue==60&&source.save_bytes()==sourceBytes,"pasted edit isolated from original and source");
    StyleDocument blank;const auto blankBytes=blank.save_bytes();require(blank.paste_pattern(payload,L"Cross Style")&&blank.patterns().size()==1&&blank.part_references(0).size()==2,"empty destination cross Style paste");const auto cross=blank.save_bytes();require(blank.undo()&&blank.save_bytes()==blankBytes&&blank.redo()&&blank.save_bytes()==cross,"cross Style whole history");
    StyleDocument invalid;invalid.load(sourceBytes);require(!invalid.paste_pattern(payload,L"")&&!invalid.paste_pattern(payload,std::wstring(256,L'x'))&&!invalid.paste_pattern(payload,std::wstring(L"x\0y",3)),"invalid paste names rejected");
    auto wrong=packet;wrong.type="SPC2";rejected([&]{invalid.paste_pattern(wrong.encode(),L"Wrong");},"unknown clipboard version refused");
    auto missing=packet;missing.children.erase(missing.children.begin());rejected([&]{invalid.paste_pattern(missing.encode(),L"Wrong");},"missing owned Part refused");
    auto duplicate=packet;duplicate.children.insert(duplicate.children.begin(),duplicate.children.front());rejected([&]{invalid.paste_pattern(duplicate.encode(),L"Wrong");},"ambiguous owned Part refused");
    auto extra=packet;extra.children.push_back(opaque);rejected([&]{invalid.paste_pattern(extra.encode(),L"Wrong");},"unversioned top-level extension refused");
    auto two=packet;two.children.push_back(two.children.back());rejected([&]{invalid.paste_pattern(two.encode(),L"Wrong");},"multiple Patterns refused");
    auto orphan=packet;auto orphanPart=orphan.children.front();orphanPart.find("prth")->data[132]^=0x40;orphan.children.insert(orphan.children.begin(),orphanPart);rejected([&]{invalid.paste_pattern(orphan.encode(),L"Wrong");},"orphan Part refused");
    auto broken=packet;put32(broken.children.front().find("note")->data,0,27);rejected([&]{invalid.paste_pattern(broken.encode(),L"Wrong");},"malformed note stride refused");
    auto truncated=payload;truncated.pop_back();rejected([&]{invalid.paste_pattern(truncated,L"Wrong");},"truncated clipboard refused");
    require(invalid.save_bytes()==sourceBytes&&!invalid.dirty()&&!invalid.undo(),"all malformed pastes retain bytes/state/history");
    StyleDocument multiple;multiple.load(sourceBytes);require(multiple.new_pattern(L"Second",7),"second distinct Part fixture");auto multiRoot=Chunk::parse(multiple.save_bytes());auto secondRef=*multiRoot.children.back().find("LIST","pref");multiRoot.find("LIST","pttn")->children.push_back(secondRef);multiRoot.children.pop_back();multiple.load(multiRoot.encode());const auto multiPayload=multiple.copy_pattern(0);
    StyleDocument multiDest;const auto multiBefore=multiDest.save_bytes();require(multiDest.paste_pattern(multiPayload,L"Two Parts"),"paste multiple distinct owned Parts");const auto multiRefs=multiDest.part_references(0);require(multiDest.parts().size()==2&&multiRefs.size()==3&&multiRefs[0].objectId==multiRefs[1].objectId&&multiRefs[0].objectId!=multiRefs[2].objectId&&multiRefs[2].pchannel==7u,"mapping keeps duplicate and distinct references");
    auto noRefs=packet;noRefs.children.erase(noRefs.children.begin());auto& children=noRefs.children.front().children;children.erase(std::remove_if(children.begin(),children.end(),[](const Chunk& c){return c.type=="pref";}),children.end());StyleDocument emptyPattern;require(emptyPattern.paste_pattern(noRefs.encode(),L"Empty Pattern")&&emptyPattern.parts().empty()&&emptyPattern.part_references(0).empty(),"Pattern without Parts is valid clipboard");
    for(const auto& pair:std::vector<std::pair<std::wstring,Bytes>>{{L"multi-source.stp",multiRoot.encode()},{L"multi-clipboard.bin",multiPayload},{L"multi-before.stp",multiBefore},{L"multi-pasted.stp",multiDest.save_bytes()}})write_file_atomic((base/pair.first).wstring(),pair.second);
    for(const auto& pair:std::vector<std::pair<std::wstring,Bytes>>{{L"original.stp",original},{L"source.stp",sourceBytes},{L"clipboard.bin",payload},{L"pasted.stp",pasted},{L"blank.stp",blankBytes},{L"cross.stp",cross},{L"plain-clipboard.bin",plain.copy_pattern(0)},{L"Heartlnd.stp",original},{L"selection.sgp",segment}})write_file_atomic((base/pair.first).wstring(),pair.second);
    Framework host;const auto si=host.open_style((base/L"Heartlnd.stp").wstring()),di=host.open_segment((base/L"selection.sgp").wstring());const auto song=host.document(di).save_bytes();
    require(host.paste_style_pattern(si,plain.copy_pattern(0),L"Playback Paste")&&host.document(di).styles()[0].bytes==host.style_document(si).save_bytes(),"Framework clipboard owned snapshot");const auto hostPaste=host.style_document(si).save_bytes();write_file_atomic((base/L"framework-pasted.stp").wstring(),hostPaste);
    require(host.undo_style(si)&&host.document(di).styles()[0].bytes==original&&host.redo_style(si)&&host.document(di).styles()[0].bytes==hostPaste,"Framework clipboard UndoRedo");
    rejected([&]{host.paste_style_pattern(si,missing.encode(),L"Wrong");},"Framework malformed clipboard refused");require(host.style_document(si).save_bytes()==hostPaste&&host.document(di).styles()[0].bytes==hostPaste,"Framework rejection retains owned cache");
    require(host.delete_style_pattern(si,0)&&host.document(di).save_bytes()==song&&!host.document(di).dirty(),"source Pattern deletion leaves independent paste and Segment unchanged");const auto final=host.style_document(si).save_bytes();
    host.save_style(si,(base/L"Heartlnd.stp").wstring());host.save_project((base/L"project.dmpj").wstring());Framework reload;reload.open_project((base/L"project.dmpj").wstring());require(reload.style_document(0).save_bytes()==final&&reload.document(0).styles()[0].bytes==final&&!reload.style_document(0).dirty(),"separate Framework clipboard restore");reload.save_style(0,(base/L"resaved.stp").wstring());require(read_file((base/L"resaved.stp").wstring())==final,"clipboard exact resave");
}
